(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  // ── Module 3 helpers: graphs, curves, contour plane ───────────────────────
  // makeGraph maps maths values to pixels with separate x and y scales.
  function makeGraph(ox, oy, sx, sy) {
    return {
      ox: ox, oy: oy, sx: sx, sy: sy,
      x: function (v) { return ox + sx * v; },
      y: function (v) { return oy - sy * v; }
    };
  }
  function curveD(g, f, a, b, n) {
    var d = "";
    for (var i = 0; i <= n; i++) {
      var v = a + ((b - a) * i) / n;
      d += (i ? " L " : "M ") + g.x(v).toFixed(1) + " " + g.y(f(v)).toFixed(1);
    }
    return d;
  }
  function setD(node, d) {
    node.setAttribute("d", d);
  }
  function fmt(v, n) {
    return (Math.round(v * 100000) / 100000).toFixed(n === undefined ? 1 : n);
  }
  function drawAxes(parent, g, xmax, ymax, xticks, yticks) {
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(xmax), y2: g.y(0), class: "axis" }, parent);
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(0), y2: g.y(ymax), class: "axis" }, parent);
    (xticks || []).forEach(function (t) { txt(parent, g.x(t), g.y(0) + 15, "tick", String(t), "middle"); });
    (yticks || []).forEach(function (t) { txt(parent, g.x(0) - 7, g.y(t) + 4, "tick", String(t), "end"); });
  }
  function card(parent, x, y, w, h, cls) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: 10, class: cls || "fillG" }, parent);
  }
  function ring(parent, cx, cy, rx, ry, cls) {
    return el("ellipse", { cx: cx, cy: cy, rx: rx, ry: ry, fill: "none", class: cls || "contour" }, parent);
  }
  function clipTo(id, x, y, w, h) {
    var c = el("clipPath", { id: id }, defs);
    el("rect", { x: x, y: y, width: w, height: h }, c);
  }

  // ── Module 4 helpers: seeded randomness, small shapes ─────────────────────
  function mulberry(seed) {
    var a = seed;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function gaussSource(rand) {
    return function () {
      var u = 1 - rand(), v = rand();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };
  }
  function box(parent, x, y, w, h, fill, stroke, r) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: r === undefined ? 6 : r, fill: fill, stroke: stroke || "none", "stroke-width": 2 }, parent);
  }
  function setBox(node, x, y, w, h) {
    node.setAttribute("x", x); node.setAttribute("y", y); node.setAttribute("width", Math.max(0, w)); node.setAttribute("height", Math.max(0, h));
  }
  function vis(list, on) {
    list.forEach(function (n) { show(n, on); });
  }

  var EXPLAIN = {"full-population":{"h":"WHAT YOU ARE LOOKING AT","t":"Here are **100 emails**. Pick one at random. Every email is equally likely to be the one you get, so **all 100 are in play**."},"event-a":{"h":"EVENT A: THE EMAIL IS SPAM","t":"**40 of the 100** emails are spam (pink). So **P(spam) = 40 / 100 = 0.4**. This is the probability before we know anything else."},"observe-b":{"h":"NEW INFORMATION: B = CONTAINS “FREE”","t":"Now you learn that the email contains the word **“free”**. **30 of the 100** emails contain it. We are being told the email is one of these 30."},"restrict-to-b":{"h":"RESTRICT ATTENTION TO B","t":"Everything outside the dashed box is **ruled out**. The universe we pick from shrank from **100 emails to 30**. That is the heart of conditioning."},"overlap":{"h":"THE OVERLAP: SPAM AND FREE","t":"Inside the 30 “free” emails, **24 are spam** (bright pink) and **6 are not**. The overlap of A and B is 24 emails."},"conditional-ratio":{"h":"THE RATIO: OVERLAP / B","t":"**P(spam | free) = P(spam and free) / P(free) = 24/100 ÷ 30/100 = 24 / 30 = 0.8.** The denominator changed from 100 to 30."},"ml-connection":{"h":"TAKEAWAY","t":"Before seeing the word, spam had probability **0.4**. Given “free”, it is **0.8**. A classifier makes every prediction this way: **conditioned on the evidence it can see**."}};
  // ── scene ──
  var steps = [
    { id: "full-population", label: "All 100 emails", caption: "Here are 100 emails. Pick one at random. Every email is equally likely to be the one you get, so all 100 are in play." },
    { id: "event-a", label: "Event A: the email is spam", caption: "40 of the 100 emails are spam (pink). So P(spam) = 40 / 100 = 0.4. This is the probability before we know anything else." },
    { id: "observe-b", label: "New information: B = contains 'free'", caption: "Now you learn the email contains the word 'free'. 30 of the 100 emails contain it. We are being told the email is one of these 30." },
    { id: "restrict-to-b", label: "Restrict attention to B", caption: "Everything outside the dashed box is ruled out. The 'universe' we pick from shrank from 100 emails to 30. That is the heart of conditioning." },
    { id: "overlap", label: "The overlap: spam AND free", caption: "Inside the 30 'free' emails, 24 are spam (bright pink) and 6 are not. The overlap of A and B is 24 emails." },
    { id: "conditional-ratio", label: "The ratio: overlap / B", caption: "P(spam | free) = P(spam and free) / P(free) = 24/100 ÷ 30/100 = 24 / 30 = 0.8. The denominator changed from 100 to 30." },
    { id: "ml-connection", label: "Evidence changes the prediction", caption: "Before seeing the word, spam had probability 0.4. Given 'free', it is 0.8. A classifier makes every prediction this way: conditioned on the evidence it can see." }
  ];

  function isFree(k) { return k < 30; }
  function isSpam(k) { return k < 24 || (k >= 30 && k < 46); }
  var dots = [];
  var gridG = el("g", {}, svg);
  for (var k = 0; k < 100; k++) {
    var c = Math.floor(k / 10), r = k % 10;
    dots.push(el("circle", { cx: 52 + c * 26, cy: 66 + r * 26, r: 9, fill: "#8fa89c", stroke: "none" }, gridG));
  }
  var freeBox = el("rect", { x: 36, y: 50, width: 3 * 26 + 2, height: 10 * 26 - 2, rx: 10, fill: "none", stroke: "#e2b44a", "stroke-width": 3, "stroke-dasharray": "7 5" }, svg);
  var freeLbl = txt(svg, 36 + 40, 44, "lbl lbl-y", "contains 'free'", "middle");
  var legend = el("g", {}, svg);
  el("circle", { cx: 130, cy: 338, r: 7, fill: "#f472b6" }, legend);
  txt(legend, 142, 342, "note", "spam", "start");
  el("circle", { cx: 190, cy: 338, r: 7, fill: "#38bdf8" }, legend);
  txt(legend, 202, 342, "note", "not spam", "start");

  var panel = el("g", {}, svg);
  card(panel, 336, 50, 290, 130, "fillG");
  var p1 = txt(panel, 481, 78, "note", "", "middle");
  var p2 = txt(panel, 481, 108, "mono", "", "middle");
  var p3 = txt(panel, 481, 140, "big", "", "middle");
  var p4 = txt(panel, 481, 166, "note", "", "middle");

  var ratioG = el("g", {}, svg);
  txt(ratioG, 336, 218, "lbl", "inside the 30 'free' emails:", "start");
  var rSpam = box(ratioG, 336, 230, 0.8 * 290, 34, "rgba(244,114,182,0.85)", "none", 4);
  var rHam = box(ratioG, 336 + 0.8 * 290, 230, 0.2 * 290, 34, "rgba(56,189,248,0.85)", "none", 4);
  txt(ratioG, 336 + 0.4 * 290, 252, "lbl", "24 spam", "middle");
  txt(ratioG, 336 + 0.9 * 290, 252, "lbl", "6", "middle");
  txt(ratioG, 336, 290, "note", "the denominator changed: 100 → 30", "start");

  var compareG = el("g", {}, svg);
  txt(compareG, 336, 214, "lbl", "before the word 'free':", "start");
  box(compareG, 336, 222, 0.4 * 290, 28, "rgba(244,114,182,0.6)", "none", 4);
  txt(compareG, 336 + 0.4 * 290 + 8, 242, "mono", "P(spam) = 0.4", "start");
  txt(compareG, 336, 276, "lbl", "after seeing 'free':", "start");
  box(compareG, 336, 284, 0.8 * 290, 28, "rgba(244,114,182,0.9)", "none", 4);
  txt(compareG, 336 + 8, 304, "mono", "P(spam | free) = 0.8", "start");

  function render(index, id) {
    var i = index;
    show(freeBox, i >= 2 && i <= 5);
    show(freeLbl, i >= 2 && i <= 5);
    show(legend, i >= 1);
    show(ratioG, i === 5);
    show(compareG, i === 6);
    p1.textContent = ""; p2.textContent = ""; p3.textContent = ""; p4.textContent = "";
    for (var q = 0; q < 100; q++) {
      var d = dots[q], spam = isSpam(q), free = isFree(q);
      var fill = i === 0 ? "#8fa89c" : (spam ? "#f472b6" : "#38bdf8");
      var op = 1, rad = 9, stroke = "none";
      if (i === 1) { op = spam ? 1 : 0.35; }
      if (i === 2) { op = free ? 1 : 0.55; }
      if (i === 3) { op = free ? 1 : 0.1; }
      if (i === 4) { op = free ? (spam ? 1 : 0.5) : 0.1; if (free && spam) { rad = 10.5; stroke = "#ffffff"; } }
      if (i === 5) { op = free ? 1 : 0.1; }
      if (i === 6) { op = 1; }
      d.setAttribute("fill", fill);
      d.setAttribute("opacity", String(op));
      d.setAttribute("r", rad);
      d.setAttribute("stroke", stroke);
      d.setAttribute("stroke-width", stroke === "none" ? 0 : 2);
    }
    if (i === 0) { p1.textContent = "random email"; p2.textContent = "100 equally likely emails"; p3.textContent = "100"; }
    if (i === 1) { p1.textContent = "A = spam"; p2.textContent = "40 of 100"; p3.textContent = "P(spam) = 0.4"; }
    if (i === 2) { p1.textContent = "B = contains 'free'"; p2.textContent = "30 of 100"; p3.textContent = "P(free) = 0.3"; p4.textContent = "we learn: it is one of these 30"; }
    if (i === 3) { p1.textContent = "new universe"; p2.textContent = "30 emails (was 100)"; p3.textContent = "only B counts now"; }
    if (i === 4) { p1.textContent = "A and B"; p2.textContent = "24 spam emails with 'free'"; p3.textContent = "overlap = 24"; p4.textContent = "6 'free' emails are not spam"; }
    if (i === 5) { p1.textContent = "P(spam | free)"; p2.textContent = "= 24 / 30"; p3.textContent = "= 0.8"; p4.textContent = "overlap ÷ size of B"; }
    if (i === 6) { p1.textContent = "conditioning on evidence"; p2.textContent = "0.4  →  0.8"; p3.textContent = "belief moved up"; p4.textContent = "same data, new information"; }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();
